"""Shortest Palindrome — KMP prefix function on s + '#' + reverse(s).

The prefix function of the combined string ends with the length of the longest
palindromic *prefix* of s; everything after it has to be mirrored in front.

Time: O(n)   Space: O(n)
"""


class Solution:
    def shortestPalindrome(self, s: str) -> str:
        if not s:
            return ""
        combined = s + "#" + s[::-1]
        lps = [0] * len(combined)
        length = 0
        for i in range(1, len(combined)):
            while length and combined[i] != combined[length]:
                length = lps[length - 1]
            if combined[i] == combined[length]:
                length += 1
                lps[i] = length
        return s[lps[-1]:][::-1] + s
